import re
fw=open('docs/framework.md').read()
refs=set(re.findall(r'R(\d+\.\d+(?:\.\d+)*[a-z]?)',fw))
res=open('work/02-research.md').read().splitlines()
rows={}
for i,l in enumerate(res):
    m=re.match(r'\|\s*(\d+\.\d+\.\d+[a-z]?)\s*\|',l)
    if m:
        cells=[c.strip() for c in l.split('|')]
        rows[m.group(1)]=(i+1,cells)
def key(s): return [int(x) if x.isdigit() else x for x in re.split(r'[.]',s)]
for r in sorted(refs,key=lambda s:[int(re.sub(r'[a-z]','',x)) for x in s.split('.')]):
    if r in rows:
        ln,c=rows[r]
        print(f"R{r} L{ln} [{c[-3]}] {c[2][:600]}\n")
    else:
        print(f"R{r} -- not a row\n")
EOF
